package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Buddhism (බුද්ධ ධර්මය).
 * Part 2: Categories 11 to 20 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankBuddhismSetsPart2 {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    
    return when (setNum) {
      11 -> if (grade == "11") set11_Grade11[(c - 1) % set11_Grade11.size] else set11[(c - 1) % set11.size]
      12 -> if (grade == "11") set12_Grade11[(c - 1) % set12_Grade11.size] else set12[(c - 1) % set12.size]
      13 -> if (grade == "11") set13_Grade11[(c - 1) % set13_Grade11.size] else set13[(c - 1) % set13.size]
      14 -> if (grade == "11") set14_Grade11[(c - 1) % set14_Grade11.size] else set14[(c - 1) % set14.size]
      15 -> if (grade == "11") set15_Grade11[(c - 1) % set15_Grade11.size] else set15[(c - 1) % set15.size]
      16 -> if (grade == "11") set16_Grade11[(c - 1) % set16_Grade11.size] else set16[(c - 1) % set16.size]
      17 -> if (grade == "11") set17_Grade11[(c - 1) % set17_Grade11.size] else set17[(c - 1) % set17.size]
      18 -> if (grade == "11") set18_Grade11[(c - 1) % set18_Grade11.size] else set18[(c - 1) % set18.size]
      19 -> if (grade == "11") set19_Grade11[(c - 1) % set19_Grade11.size] else set19[(c - 1) % set19.size]
      20 -> if (grade == "11") set20_Grade11[(c - 1) % set20_Grade11.size] else set20[(c - 1) % set20.size]
      else -> if (grade == "11") set11_Grade11[(c - 1) % set11_Grade11.size] else set11[(c - 1) % set11.size]
    }
  }

  // --- SET 11: ත්‍රිලක්ෂණය (අනිච්ච, දුක්ඛ, අනත්ත) ---
